 UUID shopifyMapping(){
 UUID connection=UUID.randomUUID(),run=UUID.randomUUID(),job=UUID.randomUUID();
 jdbc.update("INSERT INTO marketplace_connections(id,tenant_id,channel,display_name,seller_identifier,marketplace_identifier,status,credential_secret_ref,reporting_timezone,inventory_activated_at) VALUES (?,?,'SHOPIFY','Shopify fixture',? ,?,'ACTIVE','fixture','UTC',now())",connection,tenant,connection+".myshopify.com",connection+".myshopify.com");
 jdbc.update("INSERT INTO marketplace_sync_runs(id,tenant_id,marketplace_connection_id,run_type,sync_profile,status,window_start,window_end) VALUES(?,?,?,'INCREMENTAL','SHOPIFY_ORDERS','RUNNING',now()-interval '30 days',now())",run,tenant,connection);
 jdbc.update("INSERT INTO marketplace_sync_jobs(id,tenant_id,marketplace_connection_id,sync_run_id,job_type,sequence_number) VALUES(?,?,?,?,'SHOPIFY_ORDERS',1)",job,tenant,connection,run);
 var created=java.time.Instant.parse("2026-11-01T00:00:00Z");
 var product=new com.nextaicommerce.platform.shopify.ShopifyCatalogClient.Product("gid://shopify/Product/1","Product","Brand","ACTIVE",created,null,null);
 new com.nextaicommerce.platform.shopify.ShopifyCatalogRepository(jdbc).publish(tenant,connection,job,run,null,"{}",new com.nextaicommerce.platform.shopify.ShopifyCatalogClient.Page(List.of(new com.nextaicommerce.platform.shopify.ShopifyCatalogClient.Variant("gid://shopify/ProductVariant/1","gid://shopify/InventoryItem/1","DONUT-EAx12","Default Title",java.math.BigDecimal.TEN,created,"[]","[]",true,null,product)),null,false,1,1000,100),"USD");
 UUID variant=jdbc.queryForObject("SELECT id FROM shopify_variants WHERE tenant_id=? AND marketplace_connection_id=?",UUID.class,tenant,connection);
 UUID mapping=jdbc.queryForObject("INSERT INTO marketplace_sku_mappings(tenant_id,marketplace_connection_id,account_catalog_item_id,shopify_variant_id,shopify_mapping_hash,quantity_per_marketplace_unit) SELECT ?,?,?,id,mapping_hash,12 FROM shopify_variants WHERE tenant_id=? AND id=? RETURNING marketplace_sku_mappings.id",UUID.class,tenant,connection,oldItem,tenant,variant);
 jdbc.update("INSERT INTO marketplace_sku_mapping_components(tenant_id,marketplace_sku_mapping_id,account_catalog_item_id,quantity) VALUES(?,?,?,12)",tenant,mapping,oldItem);
 manifest.put("mappingCount",2);manifest.put("providerCounts",Map.of("AMAZON",1,"SHOPIFY",1));refreshRevisions();return mapping;
 }
 @Test void preservesShopifyAndAmazonQuantitiesAndQueuesInvalidation(){UUID mapping=shopifyMapping();apply(false);assertThat(jdbc.queryForObject("SELECT quantity FROM marketplace_sku_mapping_components WHERE marketplace_sku_mapping_id=? AND account_catalog_item_id=?",Integer.class,mapping,newItem)).isEqualTo(12);assertThat(jdbc.queryForObject("SELECT quantity_per_marketplace_unit FROM marketplace_sku_mappings WHERE id=?",Integer.class,mapping)).isEqualTo(12);assertThat(jdbc.queryForObject("SELECT count(*) FROM inventory_publication_dirty WHERE tenant_id=?",Integer.class,tenant)).isPositive();}
