 @Test void shopifyDryRunLeavesOriginalReferences(){UUID mapping=shopifyMapping();apply(true);assertThat(jdbc.queryForObject("SELECT account_catalog_item_id FROM marketplace_sku_mapping_components WHERE marketplace_sku_mapping_id=?",UUID.class,mapping)).isEqualTo(oldItem);}
 UUID historicalShopifyOrder(UUID mapping){UUID connection=jdbc.queryForObject("SELECT marketplace_connection_id FROM marketplace_sku_mappings WHERE id=?",UUID.class,mapping);UUID variant=jdbc.queryForObject("SELECT shopify_variant_id FROM marketplace_sku_mappings WHERE id=?",UUID.class,mapping);
 UUID order=jdbc.queryForObject("INSERT INTO shopify_orders(tenant_id,marketplace_connection_id,order_gid,order_name,source_created_at,source_updated_at,is_test,payment_status,fulfillment_status,currency,evidence_complete,observation_hash,source_document_id) SELECT tenant_id,marketplace_connection_id,'gid://shopify/Order/1','#1',now(),now(),false,'PAID','FULFILLED','USD',true,repeat('a',64),source_document_id FROM shopify_variants WHERE id=? RETURNING id",UUID.class,variant);
 jdbc.update("INSERT INTO shopify_order_lines(tenant_id,marketplace_connection_id,order_id,line_gid,variant_id,title,inventory_state,stock_scope,ordered_quantity,current_quantity,unfulfilled_quantity,requires_shipping,ownership,source_updated_at,observation_hash) VALUES(?,?,?,'gid://shopify/LineItem/1',?,'Donut','REPORTING_ONLY','REPORTING_ONLY',1,1,0,true,'MERCHANT',now(),repeat('a',64))",tenant,connection,order,variant);
 return order;
 }

