 Object jsonRow(String sql,Object...args){return new tools.jackson.databind.ObjectMapper().readValue(jdbc.queryForObject(sql,String.class,args),Object.class);}
 void metadataFixture(boolean link)throws Exception{
 if(link){UUID canonical=UUID.randomUUID();jdbc.update("INSERT INTO global_catalog_products(id,canonical_name,brand) VALUES (?,'Verified donut','Brand')",canonical);jdbc.update("UPDATE global_product_identifiers SET global_product_id=? WHERE identifier_value='012345678905'",canonical);newGlobal=canonical;}
 else jdbc.update("DELETE FROM global_product_identifiers WHERE identifier_value='012345678905'");
 jdbc.update("INSERT INTO vendor_catalog_offers(tenant_id,vendor_id,account_catalog_item_id,vendor_item_code,list_cost,currency) VALUES (?,?,?,'2302326',2.29,'USD')",tenant,vendor,oldItem);
 UUID session=jdbc.queryForObject("INSERT INTO receiving_sessions(tenant_id,created_by) VALUES(?,?) RETURNING id",UUID.class,tenant,user);
 UUID document=jdbc.queryForObject("INSERT INTO receiving_documents(tenant_id,receiving_session_id,vendor_id,document_type,document_number,original_filename,file_sha256) VALUES(?,?,?,'INVOICE','invoice-fixture','fixture.csv',repeat('a',64)) RETURNING id",UUID.class,tenant,session,vendor);
 jdbc.update("INSERT INTO receiving_document_lines(tenant_id,receiving_document_id,account_catalog_item_id,vendor_item_code,raw_data) VALUES(?,?,?,'2302326','{\"Upc\":\"012345678905\"}'::jsonb)",tenant,document,oldItem);
 manifest.put("mode",link?"LINK_GLOBAL":"ADD_IDENTIFIER");manifest.put("sourceAccount",jsonRow("SELECT to_jsonb(r)::text FROM account_catalog_items r WHERE id=?",oldItem));manifest.put("sourceProduct",jsonRow("SELECT to_jsonb(r)::text FROM global_catalog_products r WHERE id=?",oldGlobal));manifest.put("targetProduct",link?jsonRow("SELECT to_jsonb(r)::text FROM global_catalog_products r WHERE id=?",newGlobal):null);manifest.put("barcode","012345678905");pinMetadata();
 }
 void pinMetadata()throws Exception{manifest.put("supplierAliases",jsonRow("SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]')::text FROM global_product_vendor_codes r WHERE global_product_id=?",oldGlobal));String protectedJson=jdbc.queryForObject(Files.readString(Path.of("scripts/catalogue-reconciliation/metadata-protected-evidence.sql")),String.class,tenant,oldItem);manifest.put("protectedRevision",jdbc.queryForObject("SELECT md5(?::jsonb::text)",String.class,protectedJson));manifest.put("invoiceRows",jsonRow(Files.readString(Path.of("scripts/catalogue-reconciliation/metadata-invoice-evidence.sql")),tenant,oldItem));}
 void applyMetadata(boolean rollback){tx.executeWithoutResult(s->{try{jdbc.queryForObject("SELECT set_config('app.catalogue_repair',?,true)",String.class,new tools.jackson.databind.ObjectMapper().writeValueAsString(manifest));jdbc.execute(Files.readString(Path.of("scripts/catalogue-reconciliation/enrich-identity.sql")));if(rollback)s.setRollbackOnly();}catch(java.io.IOException e){throw new RuntimeException(e);}});}
