 // Stocked maintenance lane: real remaining FIFO balances, never rewritten history.
 UUID stockLocation; UUID stockLayer(UUID item,int quantity,String expiry,String cost,String status,String key,int days){
 return jdbc.queryForObject("INSERT INTO inventory_ledger_entries(tenant_id,account_catalog_item_id,location_id,entry_type,quantity,expiration_date,unit_cost,currency,source_type,occurred_at,idempotency_key,cost_status) VALUES(?,?,?,'ADJUSTMENT',?,?::date,?::numeric,'USD','TEST',now()-(?||' days')::interval,?,?) RETURNING id",UUID.class,tenant,item,stockLocation,quantity,expiry,cost,""+days,key,status);
 }
 void stockedFixture()throws Exception{
 stockLocation=jdbc.queryForObject("SELECT id FROM warehouse_locations WHERE tenant_id=? AND code='MAIN'",UUID.class,tenant);
 jdbc.update("UPDATE vendor_catalog_offers SET effective_from=current_date-10 WHERE tenant_id=?",tenant);
 jdbc.update("INSERT INTO vendor_catalog_offers(tenant_id,vendor_id,account_catalog_item_id,vendor_item_code,list_cost,currency,effective_from) VALUES(?,?,?,'2302326',3.23,'USD',current_date-10)",tenant,vendor,oldItem);
 UUID session=jdbc.queryForObject("INSERT INTO receiving_sessions(tenant_id,created_by) VALUES(?,?) RETURNING id",UUID.class,tenant,user);
 UUID doc=jdbc.queryForObject("INSERT INTO receiving_documents(tenant_id,receiving_session_id,vendor_id,document_type,document_number,original_filename,file_sha256) VALUES(?,?,?,'INVOICE','stock-invoice','fixture.csv',repeat('b',64)) RETURNING id",UUID.class,tenant,session,vendor);
 for(UUID item:List.of(oldItem,newItem))jdbc.update("INSERT INTO receiving_document_lines(tenant_id,receiving_document_id,account_catalog_item_id,vendor_item_code,raw_data) VALUES(?,?,?,'2302326','{\"Upc\":\"012345678905\"}'::jsonb)",tenant,doc,item);
 stockLayer(oldItem,54,"2030-04-06","3.80","PROVISIONAL","old-receipt",30);
 stockLayer(oldItem,18,"2030-04-06","3.23","FINAL","old-adjustment",20);
 stockLayer(oldItem,-60,"2030-04-06","3.80","FINAL","old-sales",10);
 stockLayer(newItem,36,"2030-03-22","3.8083","FINAL","new-receipt",20);
 stockLayer(newItem,-6,"2030-03-22","3.8083","FINAL","new-sales",10);
 pinStocked();
 }
 void pinStocked()throws Exception{
 manifest.put("mode","FINAL_LAYER_TRANSFER");
 manifest.put("sourceAccount",jsonRow("SELECT to_jsonb(a)::text FROM account_catalog_items a WHERE id=?",oldItem));manifest.put("targetAccount",jsonRow("SELECT to_jsonb(a)::text FROM account_catalog_items a WHERE id=?",newItem));
 manifest.put("sourceProduct",jsonRow("SELECT to_jsonb(p)::text FROM global_catalog_products p WHERE id=?",oldGlobal));
 manifest.put("targetProduct",jsonRow("SELECT to_jsonb(p)::text FROM global_catalog_products p WHERE id=?",newGlobal));
 manifest.put("workRows",Map.of("sourceInvoices",jsonRow(Files.readString(Path.of("scripts/catalogue-reconciliation/metadata-invoice-evidence.sql")),tenant,oldItem),"targetInvoices",jsonRow(Files.readString(Path.of("scripts/catalogue-reconciliation/metadata-invoice-evidence.sql")),tenant,newItem),"purchases",jsonRow("SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.id),'[]')::text FROM purchase_order_items r WHERE tenant_id=? AND account_catalog_item_id IN(?,?)",tenant,oldItem,newItem)));
 manifest.put("offers",jsonRow("SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.id),'[]')::text FROM vendor_catalog_offers o WHERE tenant_id=? AND account_catalog_item_id IN(?,?)",tenant,oldItem,newItem));
 manifest.put("invoiceRows",Map.of("source",jsonRow(Files.readString(Path.of("scripts/catalogue-reconciliation/metadata-invoice-evidence.sql")),tenant,oldItem),"target",jsonRow(Files.readString(Path.of("scripts/catalogue-reconciliation/metadata-invoice-evidence.sql")),tenant,newItem)));
 String prelude=Files.readString(Path.of("scripts/catalogue-reconciliation/stocked-pair.sql")).split("SET LOCAL lock_timeout",2)[0];
 tx.executeWithoutResult(st->{jdbc.execute(prelude);try{manifest.put("sourceLayers",jsonRow("SELECT pg_temp.stock_layers(?,?)::text",tenant,oldItem));manifest.put("targetLayers",jsonRow("SELECT pg_temp.stock_layers(?,?)::text",tenant,newItem));}catch(Exception e){throw new RuntimeException(e);}});
 refreshRevisions();
 }
 void applyStocked(boolean rollback){tx.executeWithoutResult(st->{try{jdbc.queryForObject("SELECT set_config('app.catalogue_repair',?,true)",String.class,new tools.jackson.databind.ObjectMapper().writeValueAsString(manifest));jdbc.execute(Files.readString(Path.of("scripts/catalogue-reconciliation/stocked-pair.sql")));if(rollback)st.setRollbackOnly();}catch(java.io.IOException e){throw new RuntimeException(e);}});}
 @Test void stockedConservesSeparateExpiryAndFinalFifoCostAndOriginalRows()throws Exception{
 stockedFixture();String before=(String)manifest.get("ledgerRevision");applyStocked(false);applyStocked(false);
 assertThat(jdbc.queryForObject("SELECT sum(quantity) FROM inventory_ledger_entries WHERE tenant_id=? AND account_catalog_item_id=?",Integer.class,tenant,oldItem)).isZero();
 assertThat(jdbc.queryForObject("SELECT sum(quantity) FROM inventory_ledger_entries WHERE tenant_id=? AND account_catalog_item_id=?",Integer.class,tenant,newItem)).isEqualTo(42);
 assertThat(jdbc.queryForObject("SELECT unit_cost FROM inventory_ledger_entries WHERE tenant_id=? AND source_type='CATALOGUE_RECONCILIATION' AND quantity>0",java.math.BigDecimal.class,tenant)).isEqualByComparingTo("3.23");
 assertThat(jdbc.queryForObject("SELECT count(*) FROM inventory_ledger_entries WHERE tenant_id=? AND source_type='CATALOGUE_RECONCILIATION'",Integer.class,tenant)).isEqualTo(2);
 assertThat(jdbc.queryForObject("SELECT md5(coalesce(jsonb_agg(to_jsonb(l) ORDER BY l.id),'[]')::text) FROM inventory_ledger_entries l WHERE tenant_id=? AND source_type<>'CATALOGUE_RECONCILIATION'",String.class,tenant)).isEqualTo(before);
 assertThat(jdbc.queryForObject("SELECT count(*) FROM vendor_catalog_offers WHERE tenant_id=? AND account_catalog_item_id=? AND effective_to IS NULL",Integer.class,tenant,oldItem)).isZero();
 assertThat(CatalogIdentity.vendorBindings(jdbc,tenant,vendor,"2302326").get("2302326").items()).containsExactly(newItem);
 }
