 String allocateReal(UUID item,UUID line,int each)throws Exception{
 var method=com.nextaicommerce.platform.orders.OrderRepository.class.getDeclaredMethod("allocateQuantity",UUID.class,UUID.class,String.class,UUID.class,UUID.class,java.math.BigDecimal.class);method.setAccessible(true);
 Object remaining=method.invoke(new com.nextaicommerce.platform.orders.OrderRepository(jdbc),tenant,store,"TEST-ORDER",line,item,new java.math.BigDecimal(each));assertThat((java.math.BigDecimal)remaining).isEqualByComparingTo("0");
 return jdbc.queryForObject("SELECT coalesce(jsonb_agg(jsonb_build_object('expiry',expiration_date,'cost',unit_cost,'currency',cost_currency,'quantity',quantity) ORDER BY expiration_date,unit_cost),'[]')::text FROM order_inventory_reservations WHERE tenant_id=? AND status='ACTIVE'",String.class,tenant);
 }
